function resolveLink(baseId, link) {
  const folder = baseId.split(".").slice(0, -1);
  for (const part of link.replace(/#.*$/, "").split("/")) {
    if (part === "." || part === "") continue;
    if (part === "..") folder.pop();
    else folder.push(part);
  }
  return folder.join(".");
}

