function flatten(items) {
  const seen = new Set();
  const walk = (list) => {
    for (const item of list) {
      if (item.documentId !== undefined) seen.add(item.documentId);
      if (item.children) walk(item.children);
    }
  };
  walk(items);
  return [...seen];
}

