const entries = [
  { id: "guides.auth.login", title: "Logging in", content: "Send your email and password. Read about sessions." },
  { id: "guides.auth.sessions", title: "Sessions and tokens", content: "A session ends after 30 idle minutes." },
  { id: "guides.tasks", title: "Working with tasks", content: "Create, assign and complete tasks." },
];

function search(entries, query) {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  return entries
    .map((entry) => {
      const title = entry.title.toLowerCase();
      const content = entry.content.toLowerCase();
      let score = 0;
      for (const word of words) score += (title.includes(word) ? 3 : 0) + (content.includes(word) ? 1 : 0);
      return { id: entry.id, title: entry.title, score };
    })
    .filter((result) => result.score > 0)
    .sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
}

console.log(search(entries, "session").map((entry) => entry.id));
console.log(search(entries, "assign tasks").map((entry) => `${entry.id}:${entry.score}`));
